with flattened_attrs as (select id, customer_id, created_at, items, ship_to.city as ship_city, aggregate(items, cast(0 as double), (acc, x) -> acc + x.qty * x.price, acc -> round(acc, 2)) as items_total, array_contains(map_keys(attributes), 'device') as has_device from carts where created_at >= '2024-06-01') select case when items_total >= 1430 then 'HIGH' else 'LOW' end as items_total_tier, ship_city, count(*) filter (where ship_city = 'Bangkok') as bangkok_rows, min(created_at) as first_created_at, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as duration_min, count(*) filter (where ship_city = 'London') as london_rows, grouping(case when items_total >= 1430 then 'HIGH' else 'LOW' end) as grouping_id from flattened_attrs group by grouping sets ((case when items_total >= 1430 then 'HIGH' else 'LOW' end, ship_city), (case when items_total >= 1430 then 'HIGH' else 'LOW' end)) order by bangkok_rows
